<x-layouts::app title="Reminder SMS Logs"><div class="mx-auto max-w-[1500px] space-y-4 p-4 sm:p-5 lg:p-6"><header><p class="text-[11px] font-black uppercase tracking-[.18em] text-red-500">Service Reminders</p><h1 class="mt-1 text-2xl font-black">Reminder SMS Logs</h1><p class="text-sm text-slate-500">Every reminder SMS attempt and provider response</p></header><section class="grid gap-3 sm:grid-cols-4">@foreach(['Total SMS'=>$logs->total(),'Successful'=>$logs->getCollection()->whereIn('status',['Sent','Delivered'])->count(),'Failed'=>$logs->getCollection()->where('status','Failed')->count(),'Pending'=>$logs->getCollection()->whereIn('status',['Queued','Pending'])->count()] as $k=>$v)<div class="rounded-xl border bg-white p-4 shadow-sm"><p class="text-xs text-slate-500">{{$k}}</p><p class="text-xl font-black">{{$v}}</p></div>@endforeach</section><section class="overflow-hidden rounded-xl border bg-white shadow-sm"><div class="overflow-x-auto"><table class="w-full min-w-[1100px] text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="p-3">Date / Time</th><th class="p-3">Customer / Bike</th><th class="p-3">Phone</th><th class="p-3">Message</th><th class="p-3">Status</th><th class="p-3">Provider Response</th><th class="p-3">Sent By</th></tr></thead><tbody class="divide-y">@forelse($logs as $x)<tr><td class="p-3">{{$x->created_at->format('d M Y h:i A')}}</td><td class="p-3">{{$x->reference?->bike?->customer?->name}}<div class="text-xs text-slate-400">{{$x->reference?->bike?->number}}</div></td><td class="p-3">{{$x->phone}}</td><td class="max-w-md p-3">{{str($x->message)->limit(100)}}</td><td class="p-3 font-bold">{{$x->status}}</td><td class="p-3 text-slate-500">{{$x->api_response}}</td><td class="p-3">{{$x->sender?->name?:'System'}}</td></tr>@empty<tr><td colspan="7" class="p-14 text-center text-slate-500">No reminder SMS attempts recorded.</td></tr>@endforelse</tbody></table></div><div class="p-3">{{$logs->links()}}</div></section>